private Map<String, StoredStateCommand> decodeStateCommands(byte[] value) {
    JsonNode root = read(value, "state commands");
    if (!root.isObject()) throw corrupt("state commands");
    var commands = new LinkedHashMap<String, StoredStateCommand>();
    for (Map.Entry<String, JsonNode> entry : root.properties()) {
        JsonNode command = entry.getValue();
        commands.put(entry.getKey(), new StoredStateCommand(
                requiredText(command, "payloadHash"), requiredLong(command, "revision"),
                requiredLong(command, "eventSeq")));
    }
    return Map.copyOf(commands);
}

